390.     /// Proves that Cache::remove produces the correct spec_remove view.
391.     proof fn lemma_remove_view(
392.         new_self: &Self,
393.         key: K,
394.         old_entries: alloc::collections::BTreeMap<K, CacheEntry<V>>,
395.         old_capacity: usize,
396.     )
397.         requires
398.             btreemap_view_spec(new_self.entries) == btreemap_view_spec(old_entries).remove(key),
399.             new_self.capacity == old_capacity,
400.             // Old state was well-formed (inv fields expressed via abstraction helpers):
401.             cache_contents_of(old_entries).dom().len() <= old_capacity as nat,
402.             cache_lru_of(old_entries).no_duplicates(),
403.             cache_lru_of(old_entries).to_set() == cache_contents_of(old_entries).dom(),
404.             cache_lru_of(old_entries).len() == cache_contents_of(old_entries).dom().len(),
405.         ensures
406.             new_self@ == (CacheView::<K, V> {
407.                 contents: cache_contents_of(old_entries),
408.                 capacity: old_capacity as nat,
409.                 lru_order: cache_lru_of(old_entries),
410.             }).spec_remove(key),
411.             new_self@.inv(),
412.     {
413.         broadcast use vstd::set::group_set_axioms, vstd::map::group_map_axioms,
414.             vstd::seq_lib::seq_to_set_is_finite;
415. 
416.         reveal(<Cache<_, _> as View>::view);
417.         reveal(cache_contents_of);
418.         reveal(cache_lru_of);
419. 
420.         let old_view = CacheView::<K, V> {
421.             contents: cache_contents_of(old_entries),
422.             capacity: old_capacity as nat,
423.             lru_order: cache_lru_of(old_entries),
424.         };
425. 
426.         // Apply LRU axiom
427.         axiom_cache_lru_of_remove(old_entries, new_self.entries, key);
428. 
429.         // Prove contents equality via extensional equality
430.         assert(cache_contents_of(new_self.entries) =~= cache_contents_of(old_entries).remove(key));
431. 
432.         // Prove LRU properties
433.         if old_view.contents.dom().contains(key) {
434.             // Key was present: lru_order changes to filtered version
435.             let pred = |k: K| k != key;
436.             let filtered = old_view.lru_order.filter(pred);
437. 
