439.             lemma_filter_neq_to_set(old_view.lru_order, key);
440.             lemma_filter_neq_len(old_view.lru_order, key);
441.             filtered.unique_seq_to_set();
442.         } else {
443.             // Key absent: no-op, lru_order unchanged
444.             // filter(!=key) on a seq not containing key is identity
445.         }
446.     }
447. }
